export const PLANT_MIGRATED = {"Y39fdef": {"name": "Техническое здание", "info": "Глухое здание без окон рядом с трансформаторной подстанцией Z195.", "src": "указание пользователя"}, "Y40444c": {"src": "контур выправлен по главным осям: распознанный по космоснимку зигзаг заменён Г-образным"}, "Y6ea82e": {"name": "Производственное здание с водонапорной башней", "info": "Бывший завод Ч. Берда, затем Общество Франко-русских заводов: производственное здание с водонапорной башней, 1885–1894 гг. (арх. Р. Р. фон Генрихсен, А. Л. Гольм, техник А. И. Рейнбольдт), Перевозная ул., 1, лит. Б; позднее — корпус Фольгопрокатного завода. Выявленный объект культурного наследия (приказ КГИОП № 15 от 20.02.2001), при застройке Матисова острова сохраняется. Контур и место башни — приблизительно, по фото: распознанный по космоснимку контур неточен.", "src": "фото Wikimedia Commons «Санкт-Петербург, Перевозная 1 Б» (Н. Булыкин, 2022): жёлтый корпус вдоль проезда, круглая водонапорная башня с арочными окнами за ним; сведения — citywalls.ru, «Производственное здание с водонапорной башней…»"}, "Yb16555": {"name": "Пристройка у северного торца заводоуправления", "info": "Небольшой корпус у северного торца здания заводоуправления (на схеме РГИС — тот же адрес, Лоцманская ул., 3). Высота оценена.", "src": "citywalls.ru, фрагмент схемы РГИС к публикации «Лоцманская ул., 3»"}, "Ybea863": {"src": "контур выправлен по главным осям: распознанный по космоснимку контур с «пилой» заменён Г-образным (корпус 51 × 12 м и пристройка 29 × 8 м)"}, "Ye48a35": {"name": "Техническое здание", "info": "Глухое здание без окон рядом с трансформаторной подстанцией Z195.", "src": "указание пользователя"}, "Z103": {"name": "Корпус Нового Адмиралтейства (лит. ЖД)", "info": "Кирпичный корпус с двумя ярусами высоких арочных окон; за ним — пролёты под остеклёнными фонарями. Наб. р. Фонтанки, 203, лит. ЖД. Высота оценена по фото.", "src": "citywalls.ru, «Новое Адмиралтейство. Корпус — Адмиралтейские верфи. Цех» (лит. ЖД): фрагмент схемы РГИС, фото"}, "Z117": {"name": "Канцелярия, чертёжная и бухгалтерия", "info": "Выявленный объект культурного наследия в составе комплекса построек Адмиралтейского судостроительного завода. Высота оценена.", "src": "план границ выявленного объекта культурного наследия «Комплекс построек Адмиралтейского судостроительного завода» (КГИОП, 2003; копия на citywalls.ru), № 14"}, "Z129": {"name": "Главная судостроительная мастерская с кузницей", "info": "1910 г., арх. А. И. Дмитриев (кирпичный стиль). Выявленный объект культурного наследия. Корпус с арочными щипцами пролётов, обращёнными к ковшу; за исторической частью — поздний высокий цех. Высота оценена. Ранее в модели — «Корпусосборочный цех (предстапельная сборка)» (назначение оценочное).", "src": "план границ выявленного объекта культурного наследия «Комплекс построек Адмиралтейского судостроительного завода» (КГИОП, 2003; копия на citywalls.ru), № 13; citywalls.ru, «Адмиралтейский судостроительный завод. Главная судостроительная мастерская с кузницей» (лит. АЦ), фото 2019–2025"}, "Z136": {"info": "Большой каменный эллинг (1890–1893 гг., инж. С. Н. Будзынский, Н. П. Дуткин, Н. Д. Куторга): массивное кирпичное однопролётное строение, раскрытое остеклёнными порталами на торцах. Обращённый к Неве фасад сначала завершался треугольным фронтоном с гербом, позднее, как и противоположный, получил дугообразное очертание. Продольные стены — пилоны-контрфорсы с четырьмя рядами окон между ними. Длина 129 м, ширина 35 м, высота до низа стропил 25 м; покрытие на серповидных фермах, фонарь верхнего света 1898 г. Отнесение к контуру условное.", "src": "citywalls.ru, «Эллинги Нового Адмиралтейства» (по книгам М. С. Штиглиц): размеры, высота до низа стропил, дугообразные торцы; фото PastVu № 130380 (1996); высота свода оценена по фото; план границ выявленного объекта культурного наследия «Комплекс построек Адмиралтейского судостроительного завода» (КГИОП, 2003; копия на citywalls.ru), № 3"}, "Z143": {"name": "Нарядный дом", "info": "Дом для выдачи нарядов (канцелярия), 1838 г., Э. Х. Анерт и И. Г. Гомзин, по проекту караульного дома: фасад в семь осей, арочные окна. В 1896–1898 гг. надстроен вторым этажом. Выявленный объект культурного наследия.", "src": "план границ выявленного объекта культурного наследия «Комплекс построек Адмиралтейского судостроительного завода» (КГИОП, 2003; копия на citywalls.ru), № 6; фото Wikimedia Commons «Нарядный дом Адмиралтейского судостроительного завода» (Н. Булыкин, 2022): 2 этажа, жёлтый фасад, вальмовая металлическая кровля; citywalls.ru, «Караульный дом…» (о канцелярии)"}, "Z148": {"src": "контур выправлен в прямоугольник 57,8 × 11,9 м по длинным стенам: по замечанию с места — здание ровное, выступ и зубцы были ошибочны"}, "Z153": {"name": "Мастерская между эллингами (1830-е)", "info": "Судостроительная мастерская 1830-х гг. (инж. Л. Л. Карбоньер, арх. Э. Х. Анерт, И. Г. Гомзин) между Большим и Малым каменными эллингами; во второй половине XIX в. приспособлена под мастерскую железного судостроения. Выявленный объект культурного наследия, в одной границе с Большим каменным эллингом. Высота оценена.", "src": "план границ выявленного объекта культурного наследия «Комплекс построек Адмиралтейского судостроительного завода» (КГИОП, 2003; копия на citywalls.ru), № 5; citywalls.ru, «Эллинги Нового Адмиралтейства»"}, "Z154": {"name": "Разбивочный плаз", "info": "1914 г., арх. Н. П. Козлов (модерн). Выявленный объект культурного наследия. Длинный трёхэтажный корпус вдоль Фонтанки с крупными окнами; торец — с полуциркульным остеклённым завершением. Ранее в модели — «Трубомедницкий цех» (назначение оценочное).", "src": "план границ выявленного объекта культурного наследия «Комплекс построек Адмиралтейского судостроительного завода» (КГИОП, 2003; копия на citywalls.ru), № 12; citywalls.ru, «Адмиралтейский судостроительный завод. Разбивочный плаз» (лит. АЦ1): фрагмент схемы РГИС, фото 2019–2025"}, "Z155": {"info": "Четырёхэтажный корпус за складом на Лоцманской: красные панели фасада, ленточное остекление (виден на фото склада с Лоцманской ул.). Назначение: инженерные службы и конструкторское бюро.", "src": "фото citywalls.ru к публикации «Адмиралтейские верфи. Склад» (Лоцманская ул., 1): корпус на заднем плане"}, "Z160": {"name": "Главное корабельное здание", "info": "Протяжённый, около 200 м, корпус вдоль южного берега Ново-Адмиралтейского острова. Каменное двухэтажное здание с башней с часами посередине, где размещались канцелярия, чертёжная и плазы (1830-е годы); в советское время надстроено до четырёх этажей, от башни остался барабан над кровлей.", "src": "фото Wikimedia Commons «Главное корабельное здание Адмиралтейского завода»: четыре этажа, скатная металлическая кровля, светлый фасад; citywalls.ru, «Новое Адмиралтейство»: двухэтажная главная мастерская с башней с часами, в 1929–1931 гг. надстроена двумя этажами — «башня теперь торчит из 4-этажного здания как пенёк»; в РГИС — «Главное корабельное здание», наб. р. Фонтанки, 203, лит. ЕЗ"}, "Z162": {"info": "Наб. р. Фонтанки, 203, лит. ЮП — фактически на Лоцманской ул.; 1933 г. (Росреестр), конструктивизм. Длинный двухэтажный корпус из красного кирпича вдоль улицы: в первом этаже — окна с решётками, во втором — крупные окна; цоколь из бетонных блоков, двускатная кровля из серого металла. У южного торца — погрузочная площадка с лестницей. Северный малый прямоугольник прежнего контура — отдельное одноэтажное здание N2.", "name": "Склад (Лоцманская ул., 1)", "src": "citywalls.ru, «Адмиралтейские верфи. Склад» (Лоцманская ул., 1, лит. ЮП): фото с Лоцманской ул. (Виктор М, 2011; Риэлтор, 2019–2020; Наталия, 2024), фрагмент топоплана 1932 г.; замечание с места (N2 — отдельное здание)"}, "Z165": {"name": "Производственный корпус (лит. Ж)", "info": "Кирпичный оштукатуренный двухэтажный корпус; торец с треугольным фронтоном и полуциркульным окном обращён к ковшу. Наб. р. Фонтанки, 203, лит. Ж.", "src": "citywalls.ru, «Адмиралтейский судостроительный завод. Производственный корпус» (лит. Ж): фрагмент схемы РГИС, фото с ковша"}, "Z171": {"name": "Малый каменный эллинг (эллинг № 1)", "info": "Малый каменный эллинг (1833–1838 гг., арх. Э. Х. Анерт, инж. П.-Д. Базен, Л. Л. Карбоньер, В. П. Лебедев) — первый каменный эллинг в России, построен по образцу французского. 24 кирпичных пилона с продольными аркадами несут металлическое безраспорное покрытие (отлито на заводе Ч. Берда), к Неве обращена гигантская, обычно остеклённая арка торцевого фасада с фронтоном. Около 89–92 × 28–29 м, высота 21,6 м, до конька — 26 м. В 1960-х гг. торцы закрыты новыми корпусами.", "src": "план границ выявленного объекта культурного наследия «Комплекс построек Адмиралтейского судостроительного завода» (КГИОП, 2003; копия на citywalls.ru), № 2; citywalls.ru, «Эллинги Нового Адмиралтейства»: 89 × 27,7 × 21,6 м; Кириков, Лелина, Штиглиц, 2020: 92 × 29 × 26 м"}, "Z173": {"name": "Котельная завода «Судомех»", "info": "Наб. р. Фонтанки, 203, лит. ЕЧ — фактически на Ново-Адмиралтейском острове, на берегу Мойки. Конструктивизм; по Росреестру ввод в эксплуатацию — 1840 г. (здание, видимо, сильно перестроено). С Мойки: невысокая часть с большим остеклённым проёмом, оштукатуренные корпуса в 2–3 этажа (персиковый и жёлтый), над ними — три чёрные стальные дымовые трубы на растяжках (CH1–CH3). Ранее в модели ошибочно — «Эллинг».", "src": "citywalls.ru, «Котельная завода „Судомех“» (лит. ЕЧ): фрагмент схемы РГИС — контур совпадает, фото с противоположного берега Мойки (V_Malyj, 01.2022)"}, "Z181": {"name": "Главная электрическая станция", "info": "1909–1910 гг., арх. А. И. Дмитриев (кирпичный стиль). Выявленный объект культурного наследия. Краснокирпичный двухэтажный корпус со щипцом и круглым окном.", "src": "план границ выявленного объекта культурного наследия «Комплекс построек Адмиралтейского судостроительного завода» (КГИОП, 2003; копия на citywalls.ru), № 11; citywalls.ru, «Адмиралтейский судостроительный завод. Главная электрическая станция» (лит. АЯ), фото"}, "Z182": {"name": "Заводоуправление (Лоцманская ул., 3)", "info": "Здание бывшей администрации Адмиралтейского судостроительного завода — «Малое Адмиралтейство»: 1913–1914 гг., арх. Н. П. Козлов (неоклассицизм); в 1934–1936 гг. надстроено и расширено для Ленинградского кораблестроительного института (арх. М. С. Рейзман, В. Трофимов). Объект культурного наследия регионального значения. В здании — заводоуправление; часть помещений занимает Санкт-Петербургский государственный морской технический университет (таблички у входа). По Лоцманской — колоннада большого ордера на три этажа над рустованным первым, по торцам — шестиэтажные ризалиты с фронтонами; оштукатуренные охристые фасады, белые колонны и тяги.", "src": "citywalls.ru, «Администрация Адмиралтейского судостроительного завода — ЛКИ — СПбГМТУ» (Лоцманская ул., 3): фрагмент схемы РГИС (2022) — контур совпадает; фото фасадов (Виктор М, 2012–2014; VALERA, 2016; Наталия, 2017–2024), табличка объекта культурного наследия; замечание с места: в здании — заводоуправление"}, "Z191": {"name": "Шлюпочная мастерская (административный корпус)", "info": "Новое Адмиралтейство: бывшая шлюпочная мастерская вдоль Ново-Адмиралтейского канала, ныне административный корпус (наб. р. Фонтанки, 203, лит. ЕГ — под одной литерой с караульным домом у её северо-западного торца). Контур — OpenStreetMap без караульного дома.", "src": "citywalls.ru, «Новое Адмиралтейство. Шлюпочная мастерская — Адмиралтейские верфи. Административный корпус» (лит. ЕГ), фрагмент схемы РГИС"}, "Z195": {"name": "Трансформаторная подстанция", "info": "Глухое здание без окон.", "src": "указание пользователя"}, "Z197": {"name": "Административный корпус у Фонтанки", "info": "Два объёма: западный — четырёхэтажный, восточный — двухэтажный с портиком (в 1960-х гг. — заводской детский сад, на плане 2004 г. — медпункт). Жёлтые оштукатуренные фасады, вальмовые кровли. Наб. р. Фонтанки, 203, лит. АР. Двор перед западным объёмом закрыт со стороны проезда стеной с аркой.", "src": "citywalls.ru, «Адмиралтейский судостроительный завод. Административный корпус» (лит. АР): фрагмент схемы РГИС, фото с Фонтанки; фрагмент топоплана 2004 г.: «4К» — запад, «2Н» — восток"}, "Z23": {"info": "Протяжённый (≈260 м) двухэтажный корпус вдоль ковша основной площадки: жёлтые оштукатуренные фасады, арочные окна первого этажа, двускатная кровля. Наб. р. Фонтанки, 203, лит. Д. Контур — OpenStreetMap (без пристройки Z20).", "src": "контур — OpenStreetMap; citywalls.ru, «Адмиралтейский судостроительный завод. Цех» (лит. Д): фрагмент схемы РГИС, фото с ковша", "name": "Цех вдоль ковша (лит. Д)"}, "Z27": {"src": "по замечанию с места: восточная тонкая часть — одноэтажная проходная"}, "Z3": {"name": "Главный корпус Галерного острова 1"}, "Z32": {"name": "Цех (лит. ЕЯ)", "info": "Наб. р. Фонтанки, 203, лит. ЕЯ; 1965 г. (по данным Росреестра). Приметная коробка на оконечности Ново-Адмиралтейского острова у устья Мойки, хорошо видна с Васильевского острова: сплошное серо-зелёное остекление в сетку, над ним — глухой мятный пояс; у северного торца — более высокий тёмно-зелёный блок с ленточными окнами. Высоты оценены по фото. Ранее в модели — «Административный корпус Нового Адмиралтейства».", "src": "citywalls.ru, «Адмиралтейские верфи. Цех» (лит. ЕЯ): фото с Васильевского острова (Влада, 05.2015; Galina Vabishchevich, 2010) — опознано по положению у устья Мойки и соседним «Экипажным магазинам» (лит. ЕП)"}, "Z47": {"name": "Токарная и слесарная мастерские Нового Адмиралтейства", "info": "Корпус № 29 (табличка на фасаде): со стороны проезда — бледно-жёлтый силикатный кирпич, крупные окна; во дворе — исторические кирпичные корпуса со щипцами, прорезанными полуциркульными окнами, под скатными кровлями (сурик). Наб. р. Фонтанки, 203, лит. ЖА. Высота оценена по фото.", "src": "citywalls.ru, «Новое Адмиралтейство. Токарная и слесарная мастерские — Адмиралтейские верфи. Цех» (лит. ЖА): фрагмент схемы РГИС, фото; фото Wikimedia Commons «Адмиралтейские верфи — panoramio» (И. Волков, 2009), здание справа с табличкой «29» — опознано на месте"}, "Z73": {"name": "Пристройка токарной и слесарной мастерских", "info": "Двухэтажная пристройка у южного угла корпуса Z47, стена той же высоты. По схеме РГИС выступает за периметр корпуса примерно на 2 м с юго-восточной стороны и на 1 м — с юго-западной.", "src": "указание пользователя (пристройка к Z47, 2 этажа, стена той же высоты); citywalls.ru, фрагмент схемы РГИС для лит. ЖА — уступ контура у южного угла"}, "Z76": {"info": "Протяжённый трёхэтажный корпус из серого силикатного кирпича с красными кирпичными пилястрами, с остеклёнными фонарями на кровле. Контур — OpenStreetMap.", "src": "фото Wikimedia Commons «Адмиралтейские верфи — panoramio» (И. Волков, 2009), съёмка от x −124, y 1260 на юго-запад, здание слева — опознано на месте; высота оценена по этажности"}, "Z77": {"src": "по замечанию с места: три этажа, окна первого этажа не выше 0,5 м от земли, здание не выше соседнего Z75"}, "Z82": {"name": "Три металлических сарая", "info": "Металлические сараи для леса Нового Адмиралтейства (на плане 1911 г. — № 25, 33 и 34). Выявленный объект культурного наследия. Три пролёта под отдельными кровлями; высота оценена.", "src": "план границ выявленного объекта культурного наследия «Комплекс построек Адмиралтейского судостроительного завода» (КГИОП, 2003; копия на citywalls.ru), № 7; легенда плана Нового Адмиралтейства 1911 г. (Военная энциклопедия Сытина)"}, "Z96": {"name": "Корпус вдоль Сальнобуянского канала (лит. ЭС)", "info": "Длинный двухэтажный корпус на северном берегу Сальнобуянского канала; за ним, по старым планам, стоял главный корпус чугунного завода Ч. Берда. Наб. р. Фонтанки, 203, лит. ЭС.", "src": "citywalls.ru, «Адмиралтейский судостроительный завод. Корпус» (лит. ЭС): фрагмент схемы РГИС, фото"}};
